#include "hybrid_model_bundle.h"
#include <chrono>
namespace attention_dispatcher {
bool acquire_hybrid_bundle(const CoreInfo& core,NcnnModelCache& cache,HybridModelBundle& bundle,HybridBundleLoadStats& stats,std::string& error){bundle={};stats={};auto* staged=core.staged_head_merge();if(core.execution_type!=ExecutionType::StagedHostHeadMerge||!staged){error="hybrid bundle rejected core="+core.name+" variant="+core.key.variant+" execution=single_model";return false;}auto start=std::chrono::steady_clock::now();for(int i=0;i<4;++i){if(!std::filesystem::is_regular_file(staged->heads[i].param_path)||!std::filesystem::is_regular_file(staged->heads[i].bin_path)){error="hybrid bundle file validation failed stage=head"+std::to_string(i)+" param="+staged->heads[i].param_path.string()+" bin="+staged->heads[i].bin_path.string();return false;}bundle.heads[i]=cache.get_or_load(staged->heads[i],stats.heads[i],error);if(!bundle.heads[i]){error="hybrid bundle load failed stage=head"+std::to_string(i)+" "+error;bundle={};return false;}}
if(!std::filesystem::is_regular_file(staged->output_projection.param_path)||!std::filesystem::is_regular_file(staged->output_projection.bin_path)){error="hybrid bundle file validation failed stage=projection";bundle={};return false;}bundle.output_projection=cache.get_or_load(staged->output_projection,stats.projection,error);if(!bundle.output_projection){error="hybrid bundle load failed stage=projection "+error;bundle={};return false;}stats.load_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();return true;}
}
